 import React, { useState, useEffect } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { useAuth } from '../../contexts/AuthContext'
import { supabase } from '../../lib/supabase'
import VerifiedBadge from '../VerifiedBadge'

export default function Navbar() {
    const { user, profile, signOut, isAdmin, isVerified } = useAuth()
    const navigate = useNavigate()
    const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false)
    const [unreadCount, setUnreadCount] = useState(0)

    useEffect(() => {
        if (user) {
            const getUnreadCount = async () => {
                const { count, error } = await supabase
                    .from('notifications')
                    .select('*', { count: 'exact', head: true })
                    .eq('user_id', user.id)
                    .eq('read', false)
                
                if (!error) {
                    setUnreadCount(count || 0)
                }
            }
            getUnreadCount()

            const subscription = supabase
                .channel('notifications-count')
                .on(
                    'postgres_changes',
                    {
                        event: 'INSERT',
                        schema: 'public',
                        table: 'notifications',
                        filter: `user_id=eq.${user.id}`
                    },
                    () => {
                        setUnreadCount(prev => prev + 1)
                    }
                )
                .subscribe()

            return () => {
                subscription.unsubscribe()
            }
        }
    }, [user])

    const handleSignOut = async () => {
        await signOut()
        navigate('/login')
    }

    const handleLinkClick = () => {
        setIsMobileMenuOpen(false)
    }

    return (
        <nav className="bg-green-700 text-white shadow-lg sticky top-0 z-50">
            <div className="max-w-7xl mx-auto px-4">
                <div className="flex justify-between items-center h-16">
                    <Link to="/" className="flex items-center space-x-2" onClick={handleLinkClick}>
                        <span className="text-2xl">⚽</span>
                        <span className="font-bold text-xl">PredictFC</span>
                    </Link>

                    <div className="hidden md:flex items-center space-x-1">
                        <Link to="/" className="px-3 py-2 rounded-lg hover:bg-green-600 transition">Home</Link>
                        <Link to="/feed" className="px-3 py-2 rounded-lg hover:bg-green-600 transition">Feed</Link>
                        <Link to="/matches" className="px-3 py-2 rounded-lg hover:bg-green-600 transition">Matches</Link>
                        <Link to="/community" className="px-3 py-2 rounded-lg hover:bg-green-600 transition">Community</Link>
                        <Link to="/leaderboard" className="px-3 py-2 rounded-lg hover:bg-green-600 transition">Leaderboard</Link>
                        {isAdmin && (
                            <Link to="/admin" className="px-3 py-2 rounded-lg bg-purple-600 hover:bg-purple-700 transition">🛡️ Admin</Link>
                        )}
                    </div>

                    <div className="hidden md:flex items-center space-x-3">
                        <Link to="/notifications" className="relative hover:bg-green-600 p-2 rounded-lg transition">
                            <span className="text-xl">🔔</span>
                            {unreadCount > 0 && (
                                <span className="absolute -top-1 -right-1 bg-red-500 text-white text-xs rounded-full w-5 h-5 flex items-center justify-center animate-pulse">
                                    {unreadCount > 9 ? '9+' : unreadCount}
                                </span>
                            )}
                        </Link>

                        <Link to="/profile" className="flex items-center space-x-2 hover:bg-green-600 px-3 py-2 rounded-lg transition">
                            <span className="w-8 h-8 bg-green-500 rounded-full flex items-center justify-center font-bold text-sm">
                                {profile?.username?.[0]?.toUpperCase() || user?.email?.[0]?.toUpperCase() || 'U'}
                            </span>
                            <div className="flex items-center gap-1">
                                <span className="text-sm font-medium">
                                    {profile?.username || user?.email?.split('@')[0] || 'User'}
                                </span>
                                {isVerified && <VerifiedBadge size="sm" />}
                            </div>
                        </Link>
                        <button onClick={handleSignOut} className="px-3 py-2 bg-red-600 hover:bg-red-700 rounded-lg text-sm font-medium transition">Sign Out</button>
                    </div>

                    <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="md:hidden p-2 rounded-lg hover:bg-green-600 transition focus:outline-none" aria-label="Toggle menu">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                            {isMobileMenuOpen ? (
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                            ) : (
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
                            )}
                        </svg>
                    </button>
                </div>

                <div className={`md:hidden overflow-hidden transition-all duration-300 ${isMobileMenuOpen ? 'max-h-[500px] opacity-100' : 'max-h-0 opacity-0'}`}>
                    <div className="pb-4 border-t border-green-600">
                        <div className="flex flex-col space-y-1 pt-2">
                            <Link to="/" className="px-3 py-2 rounded-lg hover:bg-green-600 transition" onClick={handleLinkClick}>Home</Link>
                            <Link to="/feed" className="px-3 py-2 rounded-lg hover:bg-green-600 transition" onClick={handleLinkClick}>Feed</Link>
                            <Link to="/matches" className="px-3 py-2 rounded-lg hover:bg-green-600 transition" onClick={handleLinkClick}>Matches</Link>
                            <Link to="/community" className="px-3 py-2 rounded-lg hover:bg-green-600 transition" onClick={handleLinkClick}>Community</Link>
                            <Link to="/leaderboard" className="px-3 py-2 rounded-lg hover:bg-green-600 transition" onClick={handleLinkClick}>Leaderboard</Link>
                            <Link to="/profile" className="px-3 py-2 rounded-lg hover:bg-green-600 transition" onClick={handleLinkClick}>Profile</Link>
                            <Link to="/notifications" className="px-3 py-2 rounded-lg hover:bg-green-600 transition flex items-center gap-2" onClick={handleLinkClick}>
                                🔔 Notifications {unreadCount > 0 && <span className="bg-red-500 text-white text-xs rounded-full px-2 py-0.5">{unreadCount}</span>}
                            </Link>
                            {isAdmin && (
                                <Link to="/admin" className="px-3 py-2 rounded-lg bg-purple-600 hover:bg-purple-700 transition flex items-center gap-2" onClick={handleLinkClick}>🛡️ Admin Panel</Link>
                            )}
                            <button onClick={() => { handleLinkClick(); handleSignOut() }} className="px-3 py-2 text-left rounded-lg bg-red-600 hover:bg-red-700 transition">Sign Out</button>
                        </div>
                    </div>
                </div>
            </div>
        </nav>
    )
}
